import type { Language } from '../context/LanguageContext';
import { getProjects } from './projects';
import { isFilled } from './content';

export const SITE_URL = 'https://bristin.world';
const SITE_NAME = 'Bristin Biju';
const HOME_TITLE = 'Bristin Biju | Brand & Graphic Designer';

export interface PageMeta {
  title: string;
  description: string;
  /** Path from the site root, e.g. '/work/gba'. */
  path: string;
  /** Absolute path of the 1200x630 share image (generated by `npm run images`). */
  image: string;
  noindex?: boolean;
  /** Above-the-fold image to preload in the static HTML (base path + sizes). */
  preloadImage?: { src: string; sizes: string };
}

/** `sizes` of the case-study cover: must match CaseStudyPage so the preload is reused. */
export const COVER_SIZES = '(min-width: 1200px) 1120px, 100vw';

const homeDescription: Record<Language, string> = {
  en: 'Bristin Biju is a brand and graphic designer with 4+ years in agencies across Dubai, Europe and Africa: brand identities, campaigns and packaging.',
  fr: "Bristin Biju est designer graphique et de marque, avec plus de 4 ans en agences à Dubaï, en Europe et en Afrique : identités de marque, campagnes et packaging.",
};

/**
 * Title / description / share image for a page. Used in the browser
 * (usePageMeta) and at build time (scripts/build-meta.mjs), so both always agree.
 */
export function pageMeta(lang: Language, slug?: string): PageMeta {
  if (!slug) {
    return { title: HOME_TITLE, description: homeDescription[lang], path: '/', image: '/og/home.jpg' };
  }
  const p = getProjects(lang).find((x) => x.slug === slug);
  if (!p) {
    return { title: `404 | ${SITE_NAME}`, description: homeDescription[lang], path: '/', image: '/og/home.jpg', noindex: true };
  }
  const name = isFilled(p.text.title) ? p.text.title : `${p.name}: ${p.category}`;
  const client = isFilled(p.client) ? p.client : p.name;
  const description = isFilled(p.text.summary)
    ? p.text.summary
    : lang === 'fr'
      ? `${p.name} (${p.category.toLowerCase()}) pour ${client}, par Bristin Biju, designer graphique et de marque.`
      : `${p.name}: ${p.category.toLowerCase()} work for ${client} by Bristin Biju, brand and graphic designer.`;
  return {
    title: `${name} | ${SITE_NAME}`,
    description,
    path: `/work/${p.slug}`,
    image: `/og/${p.slug}.jpg`,
    preloadImage: { src: p.cover, sizes: COVER_SIZES },
  };
}
